function freshState(){return {version:1,profile:'product',goals:{},completed:{},tasks:{},notes:{},reviews:[],projectTasks:{},boundaries:{},frameworks:{},minutes:45,day:0,timer:{remaining:1500,deadline:null}};}
const STORAGE=window.StudyRole?.storageKey('study-bloom-v1')||'study-bloom-v1';
function activeScope(){return {roleId:window.StudyRole?.id||'apple',profileId:state.profile};}
function requireScope(expected){if(window.StudyRole?.isSwitching?.()||expected.roleId!==(window.StudyRole?.id||'apple')||expected.profileId!==undefined&&expected.profileId!==state.profile)throw Error('角色或学习方向已变化，请重新打开后再保存。');}
let storageReady=true, state=freshState(), projectFilter='all', resourceQuery='', promptKind=0, toastTimeout, timerTick;
try{const stored=localStorage.getItem(STORAGE); if(stored)state=validateState(JSON.parse(stored));}catch{storageReady=false;}
function validateFramework(raw){
  if(!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).sort().join(',')!=='nodes,summary,updatedAt'||typeof raw.summary!=='string'||raw.summary.length>2000||!Number.isSafeInteger(raw.updatedAt)||raw.updatedAt<0||raw.updatedAt>8640000000000000||!Array.isArray(raw.nodes)||raw.nodes.length!==6)throw Error('知识框架格式有误');
  const limits=[120,500,2000,2000,30];
  const nodes=raw.nodes.map(n=>{if(!Array.isArray(n)||n.length!==5||n.some((v,i)=>typeof v!=='string'||!v.trim()||v.length>limits[i])||!Object.hasOwn(icons,n[4]))throw Error('知识节点格式有误');return n.map(v=>v.trim());});
  return {nodes,summary:raw.summary,updatedAt:raw.updatedAt};
}
function validateState(data){
  if(!data || data.version!==1 || !Object.hasOwn(profiles,data.profile))throw Error('不支持的备份格式');
  const next=freshState(); next.profile=data.profile;
  for(const key of ['goals','completed','tasks','notes','projectTasks','boundaries'])if(data[key]&&typeof data[key]==='object'&&!Array.isArray(data[key])){
    for(const [k,v]of Object.entries(data[key]).slice(0,200)){if(['__proto__','constructor','prototype'].includes(k))continue;
      if(key==='goals' && Object.hasOwn(profiles,k) && v && typeof v==='object')next[key][k]=Object.fromEntries(['goal','why','outcome','level'].filter(f=>typeof v[f]==='string').map(f=>[f,v[f].slice(0,3000)]));
      else if(key==='boundaries' && Object.hasOwn(profiles,k) && v && typeof v==='object')next[key][k]=Object.fromEntries(['must','optional','later'].map(f=>[f,Array.isArray(v[f])?v[f].filter(x=>typeof x==='string').slice(0,15).map(x=>x.slice(0,300)):profiles[k].boundaries[f]]));
      else if(key==='notes'&&typeof v==='string')next[key][k]=v.slice(0,20000);
      else if(['completed','tasks','projectTasks'].includes(key)&&typeof v==='boolean')next[key][k]=v;
    }
  }
  if(data.frameworks!==undefined){if(!data.frameworks||typeof data.frameworks!=='object'||Array.isArray(data.frameworks)||Object.keys(data.frameworks).some(k=>!Object.hasOwn(profiles,k)))throw Error('知识框架方向有误');for(const [key,value] of Object.entries(data.frameworks))next.frameworks[key]=validateFramework(value);}
  next.minutes=Number.isFinite(data.minutes)?Math.max(15,Math.min(180,Math.round(data.minutes))):45;
  next.day=Number.isInteger(data.day)?Math.max(0,Math.min(9,data.day)):0;
  next.reviews=Array.isArray(data.reviews)?data.reviews.filter(r=>r&&typeof r.date==='string'&&typeof r.text==='string'&&Object.hasOwn(profiles,r.profile)).slice(-100).map(r=>({date:r.date.slice(0,40),text:r.text.slice(0,3000),profile:r.profile})):[];
  if(data.timer&&Number.isFinite(data.timer.remaining))next.timer.remaining=Math.max(0,Math.min(1500,Math.round(data.timer.remaining)));
  if(data.timer&&Number.isFinite(data.timer.deadline)&&data.timer.deadline>0&&data.timer.deadline<Date.now()+1501000)next.timer.deadline=data.timer.deadline;
  return next;
}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageReady=false;toast('当前浏览器无法保存，请导出备份后再离开。');}window.dispatchEvent(new CustomEvent('study-app-change'));}
function toast(msg){clearTimeout(toastTimeout);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimeout=setTimeout(()=>$('#toast').hidden=true,3200);}
const profile=()=>({...profiles[state.profile],...(state.frameworks[state.profile]?{nodes:state.frameworks[state.profile].nodes}:{})});
const goal=()=>({...profile(),...(state.goals[state.profile]||{})});
const nodeKey=i=>`${state.profile}-${i}`;
const count=()=>profile().nodes.filter((_,i)=>state.completed[nodeKey(i)]).length;
const percent=()=>Math.round(count()/profile().nodes.length*100);
const currentNode=()=>Math.max(0,profile().nodes.findIndex((_,i)=>!state.completed[nodeKey(i)]));
const scope=()=>state.boundaries[state.profile]||profile().boundaries;
const taskKey=i=>`${state.profile}-${state.day}-${i}`;
const sessionNames=['画出知识框架与边界','讲清最核心的概念','完成第一个最小练习','把操作拆成稳定步骤','练一次常见失败场景','用测验找理解漏洞','做出项目的最小版本','用案例检验项目表现','整理一页速查表','演示作品并复盘'];
function page(){const hash=location.hash.slice(1);return pages.some(p=>p[0]===hash)?hash:'coach';}
function navigate(name){if(page()===name)render();else location.hash=name;window.scrollTo(0,0);}
function heading(eyebrow,title,desc,actions=''){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="heading-description">${desc}</p></div><div class="heading-actions">${actions}</div></section>`;}
function profileTabs(){return `<div class="track-tabs" role="group" aria-label="选择学习方向">${Object.entries(profiles).map(([key,p])=>`<button class="track-tab ${key===state.profile?'active':''}" data-action="profile" data-id="${key}" aria-pressed="${key===state.profile}">${key==='product'?'✦':key==='coding'?'⌘':'＋'} ${p.name}</button>`).join('')}</div>`;}
function art(){return '<div class="hero-art" aria-hidden="true"><div class="floating-note">a little every day</div><div class="bloom-illustration"><div class="stem"></div><div class="leaf left"></div><div class="leaf right"></div><div class="flower-head"><i class="petal p1"></i><i class="petal p2"></i><i class="petal p3"></i><i class="petal p4"></i><i class="petal p5"></i><div class="flower-center">˘ᴗ˘</div></div><span class="spark s1">✦</span><span class="spark s2">✧</span></div></div>';}
function mapNodes(){return `<div class="map-grid">${profile().nodes.map((n,i)=>`<button class="map-node ${state.completed[nodeKey(i)]?'is-complete':''}" data-action="node" data-id="${i}"><div class="node-top"><span class="node-icon">${icon(n[4])}</span><span class="node-step">${String(i+1).padStart(2,'0')} ${state.completed[nodeKey(i)]?'✓':''}</span></div><h3 class="node-name">${esc(n[0])}</h3><p class="node-desc">${esc(n[1])}</p><div class="node-foot"><span class="chip ${state.completed[nodeKey(i)]?'done':''}">${state.completed[nodeKey(i)]?'已通过自测':'待学习'}</span><span aria-hidden="true">↗</span></div></button>`).join('')}</div>`;}
function boundaries(){return `<div class="boundary-grid">${[['must','必须掌握','◎'],['optional','按需了解','◌'],['later','这次先不学','☾']].map(([key,title,mark])=>`<section class="boundary-card ${key}"><h3 class="boundary-title"><span>${mark}</span> ${title}</h3><ul class="boundary-list">${scope()[key].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`).join('')}</div>`;}
function resourceItems(items){return `<div class="resource-list">${items.map(r=>`<a class="resource-item" href="${r.url}" target="_blank" rel="noopener noreferrer"><span class="resource-icon">${r.emoji}</span><span><strong class="resource-title">${r.title}</strong><span class="resource-meta">${r.kind}</span></span><span class="resource-arrow">↗</span></a>`).join('')}</div>`;}
function garden(){const g=goal();return heading('YOUR LITTLE LEARNING GARDEN','今天，也让知识长大一点 <span class="heading-flower">✿</span>','少一点漫无目的，多一点学会的确定感。',`<button class="button secondary" data-action="edit-goal">${icon('target')} 设置学习目标</button>`)+
  profileTabs()+(window.StudyPlanner?.render(window.StudyApp.getContext())||'')+`<section class="hero-card"><div class="hero-copy"><span class="badge">✦ 先搭框架，再轻快出发</span><h2>先画清边界，<br>再长出你的知识树。</h2><p>知道要学什么、学到哪里、怎么证明学会。<br>把大目标，变成一小步一小步的成长。</p><div class="hero-actions"><button class="button primary" data-action="navigate" data-page="framework">搭建我的知识框架 ${icon('arrow')}</button><button class="text-button" data-action="navigate" data-page="method">看看学习方法 ↗</button></div></div>${art()}</section>`+
  `<div class="stats-grid"><div class="stat-card"><span class="stat-icon lavender">${icon('map')}</span><div><strong class="stat-value">${profile().nodes.length}<small> 个节点</small></strong><span class="stat-label">让知识有一张地图</span></div></div><div class="stat-card"><span class="stat-icon pink">${icon('check')}</span><div><strong class="stat-value">${count()}<small> / ${profile().nodes.length}</small></strong><span class="stat-label">已通过自测的节点</span></div></div><div class="stat-card"><span class="stat-icon peach">${icon('clock')}</span><div><strong class="stat-value">${state.minutes}<small> 分钟 / 次</small></strong><span class="stat-label">给今天留一点时间</span></div></div></div>`+
  `<div class="dashboard-grid"><div class="main-column"><section class="panel"><div class="panel-heading"><div><div class="section-kicker">MY KNOWLEDGE MAP</div><h2>${esc(window.StudyRole?.name||'貔貅')}的知识框架</h2></div><button class="text-button" data-action="navigate" data-page="framework">查看全部 ↗</button></div>${profileTabs()}<div class="goal-strip"><span class="goal-label">这次想做到</span><strong class="goal-value">${esc(g.goal)}</strong><button class="text-button" data-action="edit-goal">编辑</button></div>${mapNodes()}<div class="section-footer"><span>认识 → 解释 → 应用 → 排错 → 迁移</span><span>${percent()}% 已掌握</span></div><div class="progress-track"><div class="progress-fill" style="width:${percent()}%"></div></div></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">LESS, BUT BETTER</div><h2>划清边界，学得更轻松</h2></div><button class="text-button" data-action="edit-boundary">调整边界 ↗</button></div>${boundaries()}</section></div><div class="side-column"><section class="panel today-panel"><div class="panel-heading"><h2>今天的一小步</h2><span class="tag">第 ${state.day+1} 次</span></div><p class="panel-subtitle">${sessionNames[state.day]}</p>${taskList(true)}<button class="button primary wide" data-action="navigate" data-page="session">开始今日学习 ${icon('arrow')}</button></section><section class="note-card"><span class="note-icon">✿</span><div class="note-copy"><h3>学会，比学完更重要</h3><p>看完不算终点。试着关掉资料，用自己的话讲一遍，再动手做一个小例子。</p><button class="text-button" data-action="navigate" data-page="method">试试费曼复述 ↗</button></div></section><section class="panel"><div class="panel-heading"><h2>我的学习资料</h2><button class="text-button" data-action="navigate" data-page="resources" aria-label="查看全部学习资料">↗</button></div>${resourceItems(resources.slice(0,2))}</section></div></div>`;}
function framework(){return heading('FIRST THINGS FIRST','把知识地图，先画清楚','先确定目标与边界，再给每个知识节点配上练习和验收。',`<button class="button secondary" data-action="export-md">${icon('download')} 导出学习框架</button><button class="button primary" data-action="edit-goal">编辑目标</button>`)+profileTabs()+(window.StudyPlanner?.render(window.StudyApp.getContext())||'')+`<section class="panel"><div class="panel-heading"><div><h2>${esc(goal().goal)}</h2><p class="panel-subtitle">学习动机：${esc(goal().why)}</p></div><span class="tag">${esc(goal().level||'能独立应用')}</span></div><div class="goal-strip"><span class="goal-label">验收作品</span><strong class="goal-value">${esc(goal().outcome)}</strong></div><p class="source-note">${state.frameworks[state.profile]?'已保存的个人框架：'+esc(state.frameworks[state.profile].summary):state.profile==='custom'?'这是通用骨架。可以在上面输入你的主题，让旁边的 GPT 生成个人框架。':'这是起步框架，可以在上面输入目标，让旁边的 GPT 按你的用途细化。'}</p>${mapNodes()}<div class="section-footer"><span>点击节点：看练习、写笔记、对照标准自测</span><strong>${count()} / 6 已掌握</strong></div></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">KEEP YOUR FOCUS</div><h2>这一次，哪些学，哪些先放下</h2></div><button class="text-button" data-action="edit-boundary">编辑三份清单 ↗</button></div>${boundaries()}</section><section class="panel"><div class="panel-heading"><h2>把框架交给 GPT，一起细化</h2><button class="button soft small" data-action="copy-framework">${icon('copy')} 复制提示词</button></div><p class="panel-subtitle">带着你的目标、时间和边界，请 AI 补全知识依赖、练习与验收标准。你可以先审一遍，再决定学什么。</p></section>`;}
function tasks(){return state.day===0?['写清学习用途和验收作品','画出 6 个知识节点，删掉无关支线','不看资料，复述今天的知识框架']:['带着一个问题学习核心材料','完成一个小练习，记录卡住的地方','关掉资料复述，并留下一条复盘'];}
function taskList(compact=false){return `<div class="check-list">${tasks().map((t,i)=>`<label class="check-row"><input type="checkbox" data-task="${i}" ${state.tasks[taskKey(i)]?'checked':''}><span class="check-content"><span class="check-title">${t}</span>${!compact?`<span class="check-detail">${[`${Math.round(state.minutes*.25)} 分钟 · 明确输入`,`${Math.round(state.minutes*.5)} 分钟 · 动手验证`,`${state.minutes-Math.round(state.minutes*.25)-Math.round(state.minutes*.5)} 分钟 · 主动回忆`][i]}</span>`:''}</span></label>`).join('')}</div>`;}
function timerText(){let remain=state.timer.deadline?Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000)):state.timer.remaining;return `${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;}
function session(){let notes=state.notes[`session-${state.profile}-${state.day}`]||'';return heading('ONE SMALL STEP AT A TIME','今天，专心做一件小事','一次学习，一份产出。先回忆，再输入，最后动手验证。',`<button class="button secondary" data-action="edit-goal">每次 ${state.minutes} 分钟 · 调整</button>`)+`<div class="day-list" role="group" aria-label="选择学习次数">${sessionNames.map((t,i)=>`<button class="day-card ${i===state.day?'active':''}" data-action="day" data-id="${i}" aria-pressed="${i===state.day}"><span class="day-label">${String(i+1).padStart(2,'0')}</span><span class="day-title">${t.slice(0,6)}</span></button>`).join('')}</div><div class="session-layout"><div><section class="panel"><div class="panel-heading"><div><div class="section-kicker">SESSION ${String(state.day+1).padStart(2,'0')}</div><h2>${sessionNames[state.day]}</h2><p class="panel-subtitle">本次目标：${esc(goal().goal)}</p></div></div>${taskList()}<div class="callout">本次产出：${state.day===0?'一张知识地图 + 一份暂不学清单':esc(profile().nodes[Math.min(5,Math.floor(state.day*.6))][3])}</div><div class="inline-actions"><button class="button soft" data-action="copy-session">${icon('copy')} 复制给 Claude 的任务</button><button class="text-button" data-action="navigate" data-page="framework">回看知识框架 ↗</button></div></section><section class="panel"><div class="panel-heading"><div><h2>留下今天学会的东西</h2><p class="panel-subtitle">用自己的话记下来，比复制一大段更有用。输入后自动保存。</p></div><span class="tag">学习笔记</span></div><label class="field"><span>今天理解了什么？卡在了哪里？</span><textarea id="session-notes" data-note="session-${state.profile}-${state.day}" rows="7" maxlength="20000" placeholder="我现在能解释……&#10;我自己做了……&#10;还没想明白的是……">${esc(notes)}</textarea></label><div class="inline-actions"><button class="button primary" data-action="session-done">保存本次复盘 ${icon('check')}</button><button class="button secondary" data-action="copy-feynman">练一次费曼复述</button></div></section></div><div><section class="timer-card panel"><span class="badge">☁ 留一点专注时间</span><div class="timer-display" id="timer-display" aria-label="专注倒计时">${timerText()}</div><p class="panel-subtitle">25 分钟专注，然后起来伸个懒腰</p><div class="inline-actions"><button class="button primary" id="timer-toggle" data-action="timer-toggle">${state.timer.deadline?'暂停一下':'开始专注'}</button><button class="button secondary" data-action="timer-reset">重置</button></div></section><section class="note-card"><span class="note-icon">🌱</span><div class="note-copy"><h3>小小的完成，也算成长</h3><p>学会一个概念、修好一个错误、讲清一个例子，都值得记下来。</p></div></section><section class="panel"><h3>最近的复盘</h3>${state.reviews.filter(r=>r.profile===state.profile).slice(-3).reverse().map(r=>`<div class="review-entry"><small>${esc(new Date(r.date).toLocaleDateString('zh-CN'))}</small><p>${esc(r.text.slice(0,130))}</p></div>`).join('')||'<p class="empty-state">还没有复盘。今天就是很好的开始。</p>'}</section></div></div>`;}
const projects=[
  {id:'study',type:'mine',name:'知芽 · 个人学习花园',label:'我的仓库',emoji:'🌸',desc:'从当前网站出发，练习定义学习目标、设计知识地图、保存进度和验证完整流程。',tags:['产品设计','交互实践','作品集'],url:'https://github.com/pipykarchu/study',task:'画一张当前网站的用户流程，提出一个改进并验证效果。'},
  {id:'bili',type:'mine',name:'bili-learn · 视频学习助手',label:'我的仓库',emoji:'📼',desc:'围绕“看完能学会”重做学习流程：视频 → 知识框架 → 自测 → 实践笔记。',tags:['AI 学习','信息结构','内容验证'],url:'https://github.com/pipykarchu/bili-learn',task:'选择一段视频，整理 5 个概念、3 道自测题和 1 个实践任务。'},
  {id:'ip',type:'mine',name:'pikarchu · 个人 IP 展示',label:'我的仓库',emoji:'🌷',desc:'把学习成果整理成一页能被理解的作品介绍，练习讲清问题、方案与个人贡献。',tags:['职业表达','作品整理','产品叙事'],url:'https://github.com/pipykarchu/pikarchu',task:'为一个真实项目写一页案例：问题、用户、方案、结果与下一步。'},
  {id:'mini-rag',type:'practice',name:'给 5 份资料做一个小问答',label:'练习建议',emoji:'📚',desc:'用少量资料理解检索与引用。先画流程，再选工具实现，并测试“资料里没有答案”时怎么办。',tags:['RAG','知识边界','评测'],url:null,task:'整理 5 份非敏感资料，列出 10 个测试问题并记录回答的依据。'}
];
function projectPage(){const list=projects.filter(p=>projectFilter==='all'||p.type===projectFilter);return heading('LEARN BY MAKING','让学到的，变成做得到的','复用你已有的项目，从一个足够小的练习开始。')+`<div class="filter-row" role="group" aria-label="筛选项目">${[['all','全部项目'],['mine','我的 GitHub 项目'],['practice','小练习建议']].map(([id,title])=>`<button class="filter-button ${projectFilter===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${projectFilter===id}">${title}</button>`).join('')}</div><div class="projects-grid">${list.map(p=>`<article class="project-card"><div class="project-top"><span class="project-emoji">${p.emoji}</span><span class="project-type">${p.label}</span></div><h2 class="project-name">${p.name}</h2><p class="project-desc">${p.desc}</p><div class="project-tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="callout">小任务：${p.task}</div><label class="check-row"><input type="checkbox" data-project="${p.id}" ${state.projectTasks[p.id]?'checked':''}><span class="check-title">我完成了这个练习</span></label><div class="project-footer">${p.url?`<a class="button secondary small" href="${p.url}" target="_blank" rel="noopener noreferrer">打开仓库 ↗</a>`:'<span class="source-note">练习提案 · 由你选择工具完成</span>'}<button class="text-button" data-action="project-prompt" data-id="${p.id}">复制实践提示词 ↗</button></div></article>`).join('')}</div><div class="callout">职业规划里的“目标 → 章节 → 练习 → 项目 → 复盘”已融入这里。个人履历、求职记录与私人资料没有搬入网站源码。</div>`;}
function promptText(kind=promptKind){const g=goal();const common=`我正在学习：${profile().name}。\n实际用途：${g.why}\n本次目标：${g.goal}\n验收作品：${g.outcome}\n每次可用 ${state.minutes} 分钟，共 10 次。\n必须掌握：${scope().must.join('；')}。\n按需了解：${scope().optional.join('；')}。\n暂时不学：${scope().later.join('；')}。`;
  return common+'\n\n'+[
  '请先问我 3 个诊断问题，确认起点。再给出五级知识阶梯（认识、解释、应用、排错、迁移），每级列核心概念、前置依赖、一个小练习和清楚的过关标准。遵守我的边界，区分必学与选学。先给框架，等我反馈后再展开。',
  '请围绕目标，按先修关系拆成 10 次学习。每次写一个可验证目标、最少必要输入、动手练习、主动回忆问题和交付物。按我的可用时间调整任务大小，优先删除无关内容，不要堆资料。',
  '请逐题检验我对这个主题的理解。一次只问一题，先等我回答，再给反馈。逐渐增加难度，记录误解；答错后先给提示，再换一个例子复测。最后根据我的实际表现总结薄弱点，不要提前透露答案。',
  '请帮我做一页速查表，只保留实现目标最有用的核心概念、操作步骤、常见错误和适用边界。用一个小例子串起概念。标出需要查证的信息，不要捏造依据。最后留 3 个自测问题。',
  '请为这个学习目标挑选最多 3 份资源，优先官方文档或一手材料。每份说明解决哪个具体问题、先看哪一段、看完做什么练习。不确定链接时明确说明，不要编造链接。按学习顺序排列。',
  '接下来我会用自己的话解释今天学到的内容。请先等我说完，再检查事实错误、逻辑跳步、模糊术语与没有解释的假设。一次指出最关键的一个问题，让我举例或重讲。确认修正后，给一个新场景检验迁移。'
  ][kind];
}
function methodPage(){return heading('A KINDER WAY TO LEARN','给学习，一条清楚的路','先框架与边界，再用少量输入、主动回忆和真实练习推进。')+`<div class="callout"><strong>第 0 步 · 先确定方向</strong><br>我要做什么作品？必须掌握哪些知识？什么可以先不学？做到什么算学会？<button class="text-button" data-action="navigate" data-page="framework">去画我的地图 ↗</button></div><div class="flow-grid">${methods.map((m,i)=>`<article class="flow-step"><span class="step-number">${String(i+1).padStart(2,'0')}</span><h2>${m[0]}</h2><h3>${m[1]}</h3><p>${m[2]}</p><button class="text-button" data-action="select-prompt" data-id="${i}">使用这个提示词 ↗</button></article>`).join('')}</div><section class="panel" id="prompt-section"><div class="panel-heading"><div><div class="section-kicker">YOUR STUDY PARTNER</div><h2>带着你的目标，和 Claude 一起学</h2></div><button class="button primary small" data-action="copy-prompt">${icon('copy')} 复制提示词</button></div><div class="prompt-tabs" role="group" aria-label="选择学习提示词">${methods.map((m,i)=>`<button class="filter-button ${i===promptKind?'active':''}" data-action="select-prompt" data-id="${i}" aria-pressed="${i===promptKind}">${m[0]}</button>`).join('')}</div><div class="prompt-box"><pre>${esc(promptText())}</pre></div><p class="source-note">可以复制到 Claude 使用，也可以在本机版的“对话学习”中直接提问。在 Codex 内置浏览器中打开云端版，可以边聊边使用站点工具保存学习记录。</p></section><section class="panel"><h3>方法来源</h3><p class="panel-subtitle">保留你提供的 B 站视频作为方法入口。六种提示词方法参考公开文章整理；未取得视频逐字稿，也未确认视频与文章的直接来源关系。“10 倍”是原视频标题，不是本站对学习效果的保证。</p>${resourceItems(resources.slice(0,2))}</section>`;}
function resourcePage(){const found=resources.filter(r=>(r.title+r.kind+r.desc).toLowerCase().includes(resourceQuery.toLowerCase()));return heading('A SMALL, USEFUL BOOKSHELF','资料少一点，用得深一点','每份资料，都对应一个问题或一次练习。')+`<section class="panel"><div class="panel-heading"><h2>学习资料架</h2><label class="search-field">${icon('book')}<input type="search" id="resource-search" aria-label="搜索学习资料" value="${esc(resourceQuery)}" placeholder="搜索资料、项目、方法"></label></div><div id="resource-results">${resourceCards(found)}</div></section><section class="panel"><div class="panel-heading"><div><h2>自己的笔记，好好保存</h2><p class="panel-subtitle">记录先保留在本机，连接成功后同步到私人云端。换电脑登录同一账号即可恢复；左下角显示同步状态，离线时请先备份。</p></div><span class="tag">${storageReady?'本地保存':'保存不可用'}</span></div><div class="export-actions"><button class="button primary" data-action="export-json">${icon('download')} 导出完整备份</button><button class="button secondary" data-action="import">导入备份</button><button class="button secondary" data-action="export-md">导出 Markdown 框架</button></div><p class="source-note">完整备份为 JSON，包含你写下的内容。导入会替换学习记录，联网后同步到私人云端。</p></section><section class="panel"><h3>关于本地课程</h3><p class="panel-subtitle">你的本机已有 AI 产品、编程和大模型学习材料。本站先把学习框架搭好，课程文件仍保留在本机，未上传到公开仓库。</p><button class="text-button danger" data-action="reset-data">清空学习记录</button></section>`;}
function resourceCards(list){return list.length?list.map(r=>`<article class="resource-detail"><span class="resource-icon">${r.emoji}</span><div><span class="tag">${r.kind}</span><h3><a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.title} ↗</a></h3><p>${r.desc}</p></div></article>`).join(''):'<p class="empty-state">没有找到相关资料，换个关键词试试。</p>';}
function coachPage(){const g=goal();return window.studyCoach.render({roleId:window.StudyRole?.id||'apple',roleName:window.StudyRole?.name||'貔貅',roleAvatar:window.StudyRole?.avatar||'🐾',profileId:state.profile,profile:profile().name,goal:g.goal,why:g.why,outcome:g.outcome,minutes:state.minutes,boundaries:scope(),nodes:profile().nodes.map(n=>({name:n[0],description:n[1],exercise:n[2],acceptance:n[3]})),completedNodeCount:count()});}
function render(){const p=page();$('#current-page-label').textContent=pages.find(x=>x[0]===p)[1];$('#navigation').innerHTML=pages.map(([id,title,im])=>`<a href="#${id}" class="nav-item ${id===p?'active':''}" ${id===p?'aria-current="page"':''}>${icon(im)}<span>${title}</span>${id==='framework'?'<span class="nav-number">6</span>':''}</a>`).join('');$('#main-content').innerHTML=({garden,framework,session,coach:coachPage,projects:projectPage,method:methodPage,resources:resourcePage}[p])();document.title=`${pages.find(x=>x[0]===p)[1]} · 知芽 Study Bloom`;if(p==='coach')window.studyCoach.mount();const avatar=$('.avatar');if(avatar){avatar.textContent=window.StudyRole?.avatar||'🐾';avatar.setAttribute('aria-label',(window.StudyRole?.name||'貔貅')+'的学习空间');}window.StudyRole?.mount?.();}
function modal(title,content){$('#modal-title').textContent=title;$('#modal-body').innerHTML=content;for(const form of $('#modal-body').querySelectorAll('form')){form.dataset.roleId=activeScope().roleId;form.dataset.profileId=state.profile;}if(!$('#app-modal').open)$('#app-modal').showModal();}
function editGoal(){const g=goal();modal('给学习一个小小的目标',`<form id="goal-form"><div class="form-grid"><label class="field full-width">这次想学到什么程度？<input name="goal" value="${esc(g.goal)}" required maxlength="300"></label><label class="field full-width">为什么学？会用在哪里？<textarea name="why" rows="2" required maxlength="500">${esc(g.why)}</textarea></label><label class="field full-width">留下什么作品，证明学会了？<textarea name="outcome" rows="2" required maxlength="500">${esc(g.outcome)}</textarea></label><label class="field">每次可投入（分钟）<input name="minutes" type="number" min="15" max="180" step="1" value="${state.minutes}" required></label><label class="field">目标水平<select name="level">${['认识概念','解释原理','能独立应用','能够排错','能够迁移创造'].map(x=>`<option ${x===(g.level||'能独立应用')?'selected':''}>${x}</option>`).join('')}</select></label></div><p class="field-help">先写一个具体、做得到的目标。它会自动放进你的 Claude 提示词。</p><div class="modal-actions"><button type="button" class="button secondary" data-action="close-modal">再想一想</button><button type="submit" class="button primary">保存学习目标</button></div></form>`);}
function editBoundary(){modal('给这一次学习划好边界',`<form id="boundary-form">${[['must','必须掌握'],['optional','按需了解'],['later','这次先不学']].map(([key,title])=>`<label class="field">${title}<textarea name="${key}" rows="3" required maxlength="3000">${esc(scope()[key].join('\n'))}</textarea></label>`).join('')}<p class="field-help">每行一条，最多保留 15 条。拿不准的先放“按需了解”。</p><div class="modal-actions"><button class="button primary" type="submit">保存三份清单</button></div></form>`);}
function nodeModal(i){if(!Number.isInteger(i)||i<0||i>5)return;const n=profile().nodes[i];modal(`${String(i+1).padStart(2,'0')} · ${n[0]}`,`<p class="panel-subtitle">${esc(n[1])}</p><div class="callout"><strong>动手练习</strong><p>${esc(n[2])}</p></div><div class="callout"><strong>过关标准</strong><p>${esc(n[3])}</p></div><p class="source-note">更新框架后会保留原笔记，请对照新节点确认适用范围。</p></div><form id="node-form" data-id="${i}"><label class="field">我的理解 / 练习证据<textarea name="note" rows="5" maxlength="20000" placeholder="用自己的话解释，并附上练习结果或作品链接……">${esc(state.notes[nodeKey(i)]||'')}</textarea></label><label class="check-row"><input name="complete" type="checkbox" ${state.completed[nodeKey(i)]?'checked':''}><span class="check-title">我已对照标准完成自测，能够独立应用</span></label><p class="source-note">这是你的自主记录。勾选前，试着关掉资料，换个例子做一次。</p><div class="modal-actions"><button type="button" class="button secondary" data-action="close-modal">稍后再学</button><button class="button primary" type="submit">保存节点记录</button></div></form>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('提示词复制好了，去和 Claude 一起学吧。');}catch{modal('选中并复制提示词',`<label class="field">浏览器没有允许自动复制，请手动复制<textarea id="copy-fallback" rows="12" readonly>${esc(text)}</textarea></label>`);$('#copy-fallback').select();}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportMD(){const g=goal();const lines=[`# 我的学习框架 · ${profile().name}`,'',`目标：${g.goal}`,`动机：${g.why}`,`验收作品：${g.outcome}`,`每次 ${state.minutes} 分钟，10 次学习`,''];for(const[key,title]of [['must','必须掌握'],['optional','按需了解'],['later','这次先不学']])lines.push(`## ${title}`,...scope()[key].map(t=>`- ${t}`),'');lines.push('## 知识节点');profile().nodes.forEach((n,i)=>lines.push(`### ${state.completed[nodeKey(i)]?'[x]':'[ ]'} ${n[0]}`,`练习：${n[2]}`,`验收：${n[3]}`,`笔记：${state.notes[nodeKey(i)]||'待记录'}`,''));lines.push('## 学习记录');for(let i=0;i<10;i++)if(state.notes[`session-${state.profile}-${i}`])lines.push(`### 第 ${i+1} 次 · ${sessionNames[i]}`,state.notes[`session-${state.profile}-${i}`],'');download(lines.join('\n'),'知芽-学习框架.md','text/markdown;charset=utf-8');toast('学习框架已导出。');}
function confirmImport(data,learningData,backupRole){
  const expected={roleId:activeScope().roleId};
  // 未标角色的旧版备份产生于双角色功能之前，只归属原角色貔貅。
  const origin=backupRole===undefined?'apple':backupRole;
  if(!['apple','sheep'].includes(origin)){toast('备份中的角色无效，原有记录未被替换。');return;}
  if(origin!==expected.roleId){toast(`这是${origin==='apple'?'貔貅':'小羊'}的备份，请切换到对应角色再导入。原有记录未被替换。`);return;}
  try{requireScope(expected);}catch(error){toast(error.message);return;}
  modal('恢复当前角色的学习记录',`<p>只替换${esc(window.StudyRole?.name||'貔貅')}的目标、笔记和进度，并在连接成功后同步。另一个角色的记录不受影响。建议先导出当前记录。</p><div class="modal-actions"><button class="button secondary" data-action="export-json">先备份当前记录</button><button class="button primary" id="confirm-import">确认导入</button></div>`);
  $('#confirm-import').addEventListener('click',()=>{try{requireScope(expected);if(learningData!==undefined)window.StudyLearning.importData(learningData);}catch(error){toast(window.StudyRole?.isSwitching?.()?error.message:'学习测验备份格式有误，原有记录未被替换。');return;}state=data;state.timer.deadline=null;save();$('#app-modal').close();render();toast('当前角色的备份已恢复，可以继续学习了。');},{once:true});
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action;const id=button.dataset.id;
  if(a==='navigate')navigate(button.dataset.page);
  else if(a==='edit-goal')editGoal();
  else if(a==='edit-boundary')editBoundary();
  else if(a==='close-modal')$('#app-modal').close();
  else if(a==='node')nodeModal(Number(id));
  else if(a==='profile'&&Object.hasOwn(profiles,id)){state.profile=id;save();render();}
  else if(a==='day'){state.day=Math.max(0,Math.min(9,Number(id)));save();render();}
  else if(a==='filter'){projectFilter=id;render();}
  else if(a==='select-prompt'){promptKind=Number(id);if(page()!=='method')navigate('method');else render();$('#prompt-section')?.scrollIntoView({behavior:'smooth',block:'start'});}
  else if(a==='copy-prompt')await copy(promptText());
  else if(a==='copy-framework')await copy(promptText(0));
  else if(a==='copy-feynman')await copy(promptText(5));
  else if(a==='copy-session')await copy(promptText(1)+`\n\n今天是第 ${state.day+1} 次：${sessionNames[state.day]}。今天只完成这一小步，请先诊断，再指导练习。`);
  else if(a==='project-prompt'){const p=projects.find(p=>p.id===id);if(p)await copy(promptText(1)+`\n\n用这个项目练习：${p.name}。\n任务：${p.task}\n请先让我说明现状，再帮助拆分可验证步骤。不要直接替我完成所有答案。`);}
  else if(a==='timer-toggle'){if(state.timer.deadline){state.timer.remaining=Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000));state.timer.deadline=null;}else{if(state.timer.remaining===0)state.timer.remaining=1500;state.timer.deadline=Date.now()+state.timer.remaining*1000;}save();render();}
  else if(a==='timer-reset'){state.timer={remaining:1500,deadline:null};save();render();}
  else if(a==='session-done'){const note=state.notes[`session-${state.profile}-${state.day}`]||'';if(note.trim().length<5){toast('先用自己的话写下至少一句复盘，再保存吧。');$('#session-notes').focus();return;}state.reviews.push({date:new Date().toISOString(),text:note.slice(0,3000),profile:state.profile});state.reviews=state.reviews.slice(-100);save();render();toast('今天的成长记下来了，做得好。');}
  else if(a==='export-json'){download(JSON.stringify({...state,roleId:window.StudyRole?.id||'apple',learning:window.StudyLearning.exportData()},null,2),'知芽-'+(window.StudyRole?.name||'貔貅')+'-学习备份.json','application/json;charset=utf-8');toast('当前角色的完整备份已导出，请保存到自己的文件夹。');}
  else if(a==='export-md')exportMD();
  else if(a==='import'){$('#import-file').value='';$('#import-file').click();}
  else if(a==='reset-data'){const expected={roleId:activeScope().roleId};modal('清空当前角色的学习记录',`<p>只清空${esc(window.StudyRole?.name||'貔貅')}的目标、进度、笔记和复盘，并同步清空这个角色的云端记录。另一个角色不受影响。请先备份，确认后再清空。</p><div class="modal-actions"><button class="button secondary" data-action="export-json">先备份</button><button class="button secondary" data-action="close-modal">保留记录</button><button class="button primary" id="confirm-reset">确认清空</button></div>`);$('#confirm-reset').addEventListener('click',()=>{try{requireScope(expected);}catch(error){toast(error.message);return;}state=freshState();for(const id of Object.keys(profiles))window.StudyLearning.reset(id);save();$('#app-modal').close();render();toast('当前角色的记录已清空，从一颗新芽开始。');},{once:true});}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.task!==undefined){state.tasks[taskKey(Number(el.dataset.task))]=el.checked;save();}else if(el.dataset.project){state.projectTasks[el.dataset.project]=el.checked;save();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}else if(el.id==='resource-search'){resourceQuery=el.value;$('#resource-results').innerHTML=resourceCards(resources.filter(r=>(r.title+r.kind+r.desc).toLowerCase().includes(resourceQuery.toLowerCase())));}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target, fd=new FormData(form);
  if(['goal-form','boundary-form','node-form'].includes(form.id)){try{requireScope({roleId:form.dataset.roleId,profileId:form.dataset.profileId});}catch(error){toast(error.message);return;}}
  if(form.id==='goal-form'){state.goals[state.profile]={goal:String(fd.get('goal')).trim(),why:String(fd.get('why')).trim(),outcome:String(fd.get('outcome')).trim(),level:String(fd.get('level'))};state.minutes=Math.max(15,Math.min(180,Number(fd.get('minutes'))));}
  else if(form.id==='boundary-form'){state.boundaries[state.profile]=Object.fromEntries(['must','optional','later'].map(k=>[k,String(fd.get(k)).split('\n').map(s=>s.trim()).filter(Boolean).slice(0,15)]));}
  else if(form.id==='node-form'){const i=Number(form.dataset.id);state.notes[nodeKey(i)]=String(fd.get('note'));state.completed[nodeKey(i)]=fd.get('complete')==='on';}
  else return;save();$('#app-modal').close();render();toast('保存好了，小芽继续长大。');
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2000000){toast('备份文件过大，请选择知芽导出的 JSON 文件。');return;}try{const imported=JSON.parse(await file.text());confirmImport(validateState(imported),imported.learning,imported.roleId);}catch{toast('没有识别出有效备份，请选择知芽导出的 JSON 文件。');}});
$('#app-modal').addEventListener('click',e=>{if(e.target===$('#app-modal')){const r=$('#app-modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#app-modal').close();}});
window.addEventListener('hashchange',()=>{render();$('#main-content').focus({preventScroll:true});});
$('#github-link').innerHTML=icon('github');
$('#today-label').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
window.StudyApp=Object.freeze({
  getStorageStatus(){return {available:storageReady};},
  exportData(){const data=JSON.parse(JSON.stringify(state));if(data.timer.deadline)data.timer.remaining=Math.max(0,Math.ceil((data.timer.deadline-Date.now())/1000));data.timer.deadline=null;return data;},
  validateData(raw){const clean=validateState(raw);clean.timer.deadline=null;return clean;},
  importData(raw){if(raw?.roleId!==undefined&&raw.roleId!==activeScope().roleId)throw Error('不能导入另一个角色的学习记录');const clean=this.validateData(raw);state=clean;save();render();return true;},
  getContext(){const g=goal();return {roleId:window.StudyRole?.id||'apple',roleName:window.StudyRole?.name||'貔貅',roleAvatar:window.StudyRole?.avatar||'🐾',profileId:state.profile,level:g.level||'能独立应用',profile:profile().name,goal:g.goal,why:g.why,outcome:g.outcome,minutes:state.minutes,boundaries:JSON.parse(JSON.stringify(scope())),nodes:profile().nodes.map((n,i)=>({index:i,name:n[0],description:n[1],exercise:n[2],acceptance:n[3],completed:Boolean(state.completed[nodeKey(i)]),note:state.notes[nodeKey(i)]||''}))};},
  selectProfile(id){if(!Object.hasOwn(profiles,id))throw Error('请选择有效学习方向');state.profile=id;save();render();return this.getContext();},
  updateGoal(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['goal','why','outcome','minutes','level'].includes(k)))throw Error('目标字段无效');const next={...(state.goals[state.profile]||{})};if(Object.hasOwn(input,'level')){if(!['认识概念','解释原理','能独立应用','能够排错','能够迁移创造'].includes(input.level))throw Error('请选择有效目标水平');next.level=input.level;}for(const k of ['goal','why','outcome'])if(Object.hasOwn(input,k)){if(typeof input[k]!=='string'||!input[k].trim()||input[k].length>3000)throw Error('请填写1至3000字的目标说明');next[k]=input[k].trim();}if(Object.hasOwn(input,'minutes')&&(!Number.isInteger(input.minutes)||input.minutes<15||input.minutes>180))throw Error('学习时间应为15至180分钟');state.goals[state.profile]=next;if(Object.hasOwn(input,'minutes'))state.minutes=input.minutes;save();render();return this.getContext();},
  updateBoundaries(input){if(!input||Object.keys(input).sort().join(',')!=='later,must,optional')throw Error('请提供必学、选学和暂不学三份清单');const next={};for(const k of ['must','optional','later']){if(!Array.isArray(input[k])||input[k].length>15||input[k].some(s=>typeof s!=='string'||!s.trim()||s.length>300))throw Error('每份边界最多15条，每条1至300字');next[k]=input[k].map(s=>s.trim());}state.boundaries[state.profile]=next;save();render();return this.getContext();},
  applyFramework(input){
    if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['roleId','profileId','summary','nodes','boundaries'].includes(k))||input.roleId!==(window.StudyRole?.id||'apple')||input.profileId!==state.profile)throw Error('角色或学习方向已变化，请重新读取当前目标再生成');
    if(!Array.isArray(input.nodes)||input.nodes.length!==6)throw Error('请提供6个知识节点');
    const nodes=input.nodes.map((n,i)=>{if(!n||Object.keys(n).sort().join(',')!=='acceptance,description,exercise,title')throw Error('知识节点字段有误');return [n.title,n.description,n.exercise,n.acceptance,['target','map','book','spark','project','garden'][i]];});
    const frame=validateFramework({nodes,summary:input.summary,updatedAt:Date.now()});
    const b=input.boundaries;if(!b||Object.keys(b).sort().join(',')!=='later,must,optional')throw Error('请提供三份学习边界');for(const k of ['must','optional','later'])if(!Array.isArray(b[k])||b[k].length>15||b[k].some(v=>typeof v!=='string'||!v.trim()||v.length>300))throw Error('学习边界格式有误');
    state.frameworks[state.profile]=frame;state.boundaries[state.profile]=Object.fromEntries(Object.entries(b).map(([k,v])=>[k,v.map(t=>t.trim())]));for(let i=0;i<6;i++)state.completed[nodeKey(i)]=false;save();render();return {roleId:input.roleId,profileId:input.profileId,framework:frame,notesPreserved:true,nodeChecksReset:true};
  },
  recordNote(index,text){if(!Number.isInteger(index)||index<0||index>5||typeof text!=='string'||!text.trim()||text.length>20000)throw Error('请选择有效节点并填写1至20000字的笔记');state.notes[nodeKey(index)]=text.trim();save();render();return {nodeIndex:index,note:state.notes[nodeKey(index)]};},
  refresh(){render();}
});
render();
if(!storageReady)toast('当前浏览器无法恢复本地记录，建议导出备份。');
timerTick=setInterval(()=>{if(!state.timer.deadline)return;const display=$('#timer-display');if(display)display.textContent=timerText();if(state.timer.deadline<=Date.now()){state.timer={remaining:0,deadline:null};save();if(page()==='session')render();toast('专注时间到了，休息一下，再记录一个小收获。');}},1000);
